/** Addresses are stored and compared lowercased, so case is not a second account. */
export function normalizeEmail(email: string): string {
  return email.toLowerCase();
}

/**
 * Lookup is case-insensitive. Rows written before addresses were normalized
 * still match, because the comparison lowercases the stored value too.
 */
export async function findUserByEmail(email: string): Promise<User | null> {
  const normalized = normalizeEmail(email);
  const rows = getDb()
    .select()
    .from(users)
    .where(sql`lower(${users.email}) = ${normalized}`)
    .all();
  const row = rows.at(0);
  return row ? toUser(row) : null;
}

