/** Buckets guarding the unauthenticated endpoints. */
const LOGIN_BUCKET = "auth:login";
const REGISTER_BUCKET = "auth:register";
const RESET_BUCKET = "auth:password-reset";

const WORKSPACE_NAME_SUFFIX = "'s workspace";

input.old_string:
export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const existing = await userRepo.findUserByEmail(input.email);
  if (existing) {
    throw new Error("An account with that email already exists");
  }

  const user = await userRepo.insertUser({
    email: input.email,
    name: input.name,
    passwordHash: await hashPassword(input.password),
  });

  // A reserved or awkward name is handled downstream: `createOrganization`
  // runs the slug through `uniqueSlug()`, which skips reserved words and
  // suffixes collisions.
  const org = await createOrganization(user.id, {
    name: `${input.name}'s workspace`,
    slug: slugify(input.name) || "workspace",
    plan: "free",
  });

input.new_string:
/** Keeps `<display name>'s workspace` inside the workspace name limit. */
function workspaceName(displayName: string): string {
  const full = `${displayName}${WORKSPACE_NAME_SUFFIX}`;
  if (full.length <= ORGANIZATION_NAME_MAX_LENGTH) return full;
  const room = ORGANIZATION_NAME_MAX_LENGTH - WORKSPACE_NAME_SUFFIX.length;
  return `${displayName.slice(0, Math.max(0, room)).trimEnd()}${WORKSPACE_NAME_SUFFIX}`;
}

export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, REGISTER_BUCKET);
  if (!verdict.allowed) {
    throw new RateLimitedError(REGISTER_BUCKET, verdict.resetAt);
  }

  const email = input.email.toLowerCase();
  const existing = await userRepo.findUserByEmail(email);
  if (existing) {
    throw new DuplicateAccountError();
  }

  const user = await userRepo.insertUser({
    email,
    name: input.name,
    passwordHash: await hashPassword(input.password),
  });

  const taken = await orgRepo.listTakenOrgSlugs(workspaceSlugPrefix(input.name));
  const org = await createOrganization(user.id, {
    name: workspaceName(input.name),
    slug: deriveWorkspaceSlug(input.name, taken),
    plan: "free",
  });

