import { beforeEach, describe, expect, it } from "vitest";
import { toAppError } from "@/lib/errors";
import { consumeRateLimit, getBucketConfig, resetRateLimits } from "@/lib/rate-limit";
import { ORGANIZATION_NAME_MAX_LENGTH } from "@/schemas/organization";
import { getDb } from "@/server/db";
import { users } from "@/server/db/schema/users";
import { subscriptions } from "@/server/db/schema/billing";
import { members } from "@/server/db/schema/members";
import {
  confirmPasswordReset,
  login,
  register,
  requestPasswordReset,
} from "@/server/services/auth-service";
import type { OrgId } from "@/types/common";
import { setupTestDb, resetTestDb } from "../helpers/db";

const ANON = "00000000000000000000000000" as OrgId;
const PASSWORD = "Correct1Horse2";

async function signUp(name: string, email: string) {
  return register({
    name,
    email,
    password: PASSWORD,
    confirmPassword: PASSWORD,
    acceptTerms: true,
  });
}

describe("register", () => {
  beforeEach(async () => {
    await setupTestDb();
    await resetTestDb();
    resetRateLimits();
  });

  it("accepts reserved, short, and non-latin names", async () => {
    const cases = ["Admin", "Al", "J", "山田", "Support", "Billing", "Taskflow"];
    for (const name of cases) {
      const { user, org } = await signUp(name, `${name}@example.com`);
      expect(user.email).toBe(`${name.toLowerCase()}@example.com`);
      expect(org.name.endsWith("'s workspace")).toBe(true);
      expect(org.name.length).toBeLessThanOrEqual(ORGANIZATION_NAME_MAX_LENGTH);
      expect(org.plan).toBe("free");
      expect(org.slug.length).toBeGreaterThanOrEqual(2);
      expect(["admin", "billing", "support", "taskflow"]).not.toContain(org.slug);
    }
  });

  it("shortens a long workspace name and keeps the suffix", async () => {
    const name = "N".repeat(80);
    const { org } = await signUp(name, "long@example.com");
    expect(org.name.length).toBeLessThanOrEqual(64);
    expect(org.name.endsWith("'s workspace")).toBe(true);
  });

  it("treats email case as one account and refuses the duplicate", async () => {
    const first = await signUp("Ada", "Ada@Example.com");
    expect(first.user.email).toBe("ada@example.com");
    await expect(signUp("Ada", "ada@example.com")).rejects.toThrow(/already exists/);
    try {
      await signUp("Ada", "ADA@example.com");
    } catch (error) {
      expect(toAppError(error).code).toBe("conflict");
    }
    const rows = getDb().select().from(users).all();
    expect(rows).toHaveLength(1);
    const signedIn = await login({
      email: "ADA@example.com",
      password: PASSWORD,
      rememberMe: false,
    });
    expect(signedIn.user.id).toBe(first.user.id);
  });

  it("starts an active free subscription and one owner membership", async () => {
    const { org, user } = await signUp("Ada Lovelace", "ada@example.com");
    const sub = getDb().select().from(subscriptions).all();
    expect(sub).toHaveLength(1);
    expect(sub[0]?.plan).toBe("free");
    expect(sub[0]?.status).toBe("active");
    const memberRows = getDb().select().from(members).all();
    expect(memberRows).toHaveLength(1);
    expect(memberRows[0]?.role).toBe("owner");
    expect(memberRows[0]?.userId).toBe(user.id);
    expect(org.slug).toBe("ada-lovelace");
  });

  it("throttles sign-up, sign-in and reset confirmation as rate_limited", async () => {
    const registerCap = getBucketConfig("auth:register").capacity;
    for (let i = 0; i < registerCap; i += 1) {
      expect((await consumeRateLimit(ANON, "auth:register")).allowed).toBe(true);
    }
    await expect(signUp("Ada", "ada@example.com")).rejects.toThrow(/Rate limit/);
    try {
      await signUp("Ada", "ada@example.com");
    } catch (error) {
      expect(toAppError(error).code).toBe("rate_limited");
    }
    expect(getDb().select().from(users).all()).toHaveLength(0);

    resetRateLimits();
    const loginCap = getBucketConfig("auth:login").capacity;
    for (let i = 0; i < loginCap; i += 1) {
      await consumeRateLimit(ANON, "auth:login");
    }
    try {
      await login({ email: "ada@example.com", password: PASSWORD, rememberMe: false });
    } catch (error) {
      expect(toAppError(error).code).toBe("rate_limited");
    }

    resetRateLimits();
    const resetCap = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < resetCap; i += 1) {
      await consumeRateLimit(ANON, "auth:password-reset");
    }
    await expect(requestPasswordReset({ email: "ada@example.com" })).resolves.toBeUndefined();
    try {
      await confirmPasswordReset({
        token: "t".repeat(20),
        password: PASSWORD,
        confirmPassword: PASSWORD,
      });
    } catch (error) {
      expect(toAppError(error).code).toBe("rate_limited");
    }
  });
});

